        pcall(function() if type(readfile)=='function' then D.baseEggVisuals.hideMine=game:GetService('HttpService'):JSONDecode(readfile('tenshi_do_test_hide_my_eggs_'..tostring(D.player.UserId)..'.json'))==true end end)
